func fetch(ctx context.Context) (string, error) {
	result := make(chan string, 1) // BUFFERED: send never blocks
	go func() {
		time.Sleep(2 * time.Second)
		result <- "data" // succeeds into the buffer even if we returned
	}()
	select {
	case r := <-result:
		return r, nil
	case <-ctx.Done():
		return "", ctx.Err() // goroutine can still finish -> no leak
	}
}
